import React, {useState,useEffect,useRef,useMemo} from 'react';
import {createRoot} from 'react-dom/client';
import {Home,BarChart3,History,Mic,Sparkles,PanelsTopLeft,Settings,ArrowUp,ArrowUpRight,ChevronRight,ChevronDown,Plus,X,Minus,Square,Copy,Check,Search,Trash2,Pencil,Download,Upload,Folder,FolderSearch,Volume2,VolumeX,Monitor,Keyboard,Shield,Globe,BookOpen,FileText,Command,Plug,Zap,LoaderCircle,MoreHorizontal,RotateCcw,Send,StopCircle,MessageSquare,HardDrive,CheckCircle2,AlertCircle,SlidersHorizontal,AudioLines} from 'lucide-react';
import './style.css';
