  {route==='dictation'&&<><PageHeading title="Диктовка" description="Говорите естественно. Получайте текст в своём стиле." action={<Button icon={isRecording?Square:Mic} variant="primary" busy={busy.record} disabled={recordWorking&&!isRecording} onClick={()=>record()}>{recordingLabel}</Button>}/><Tabs items={['general','dictionary','snippets','appStyles']} labels={['Общие','Словарь','Текстовые шаблоны','Стиль по приложениям']} value={dictationTab} onChange={setDictationTab}/>{dictationTab==='general'&&<><Section title="Обработка текста" description="Выберите, насколько менять вашу речь."><div className="mode-grid">{[['none','Без изменений','Сохранить исходные слова.'],['light','Лёгкая правка','Убрать слова-паразиты и повторы.'],['polished','Отредактированный','Исправить грамматику и сделать текст яснее.']].map(([id,title,description])=><button key={id} className={`mode-card ${s.polish===id?'active':''}`} onClick={()=>save({polish:id})}><span className="mode-radio">{s.polish===id&&<span/>}</span><h3>{title}</h3><p>{description}</p><div className="mode-example">{id==='none'?'Ну давай тогда встречу перенесём на пятницу то есть на четверг':id==='light'?'Давай перенесём встречу на четверг.':'Давайте перенесём встречу на четверг.'}</div></button>)}</div><p className="footnote">Правка и перевод используют локальную модель агента. Результат может требовать проверки.</p></Section><Section title="Язык и стиль"><Row title="Стиль письма" description="Используется при обработке текста."><Select label="Стиль письма" value={s.writingStyle} options={styles} onChange={v=>save({writingStyle:v})}/></Row><Row title="Язык речи" description="Можно говорить на нескольких языках."><Select label="Язык речи" value={s.language} options={languages} onChange={v=>save({language:v})}/></Row><Row title="Перевод" description="Переводить весь распознанный текст."><Select label="Язык перевода" value={s.translateTo} options={[["","Выключен"],...languages.filter(x=>x[0]!=='auto').map(([v,label])=>[label,label])]} onChange={v=>save({translateTo:v})}/></Row><Row title="Автоматическая вставка" description="При записи сочетанием клавиш вставлять текст в активное поле."><Toggle label="Автоматическая вставка" value={s.autoPaste} onChange={v=>save({autoPaste:v})}/></Row></Section><Section title="Микрофон"><Row title="Устройство ввода" description="Список устройств Windows."><Select label="Микрофон" value={s.microphone} options={[[-1,'Системный по умолчанию'],...devices.map(d=>[d.id,d.name])]} onChange={v=>save({microphone:Number(v)})}/><IconButton icon={RotateCcw} label="Обновить устройства" onClick={()=>run('refresh',refresh)}/></Row></Section>{lastText&&<Section title="Только что распознано" action={<Button icon={Copy} onClick={()=>copy(lastText)}>Копировать</Button>}><p className="result-text">{lastText}</p></Section>}</>}{dictationTab==='dictionary'&&<Collection items={data.dictionary} title="Ваш словарь" description="Имена, названия и термины, которые стоит распознавать точно." empty="Добавьте первое слово" onAdd={()=>setModal({kind:'dictionary',title:'Добавить слово',item:{}})} onEdit={item=>setModal({kind:'dictionary',title:'Изменить слово',item})} onDelete={item=>deleteItem('dictionary',item)} render={item=><><b>{item.word}</b><p>{item.hint||'Без подсказки'}</p></>}/>} {dictationTab==='snippets'&&<Collection items={data.snippets} title="Текстовые шаблоны" description="Произнесите короткую фразу, чтобы вставить заранее подготовленный текст." empty="Создайте первый шаблон" onAdd={()=>setModal({kind:'snippets',title:'Добавить шаблон',item:{}})} onEdit={item=>setModal({kind:'snippets',title:'Изменить шаблон',item})} onDelete={item=>deleteItem('snippets',item)} render={item=><><b>{item.trigger}</b><p>{item.text}</p></>}/>} {dictationTab==='appStyles'&&<><Section title="Стиль по приложениям" description="Стиль текста для активного приложения при записи горячей клавишей." action={<Button icon={Plus} onClick={()=>setModal({kind:'appStyle',title:'Добавить стиль',item:{}})}>Добавить</Button>}>{s.appStyles.length?s.appStyles.map((item,i)=><div className="collection-row" key={i}><div><b>{item.app}</b><p>{styles.find(x=>x[0]===item.style)?.[1]||item.style}</p></div><IconButton icon={Pencil} label="Изменить стиль" onClick={()=>setModal({kind:'appStyle',title:'Изменить стиль',item,index:i})}/><IconButton icon={Trash2} label="Удалить стиль" onClick={()=>save({appStyles:s.appStyles.filter((_,j)=>j!==i)})}/></div>):<Empty icon={PanelsTopLeft} title="Один голос. Разные стили.">Добавьте имя приложения, например Outlook или Telegram, и выберите подходящий стиль.</Empty>}</Section></>}</>}
